```c
static const uint8_t sbox[256] = {...};

static void key_expand(const uint8_t *key, int nk, int nr, uint8_t *roundkeys) {
    // nk = number of 32-bit words in key (4, 6, 8)
    // nr = number of rounds (10, 12, 14)
    // total words = 4*(nr+1)
    uint32_t w[4*(14+1)];
    int i;
    for (i = 0; i < nk; i++) {
        w[i] = (key[4*i] << 24) | (key[4*i+1] << 16) | (key[4*i+2] << 8) | key[4*i+3];
    }
    for (i = nk; i < 4*(nr+1); i++) {
        uint32_t temp = w[i-1];
        if (i % nk == 0) {
            // RotWord + SubWord + Rcon
            temp = (sbox[(temp >> 16) & 0xFF] << 24) | (sbox[(temp >> 8) & 0xFF] << 16) | (sbox[temp & 0xFF] << 8) | sbox[(temp >> 24) & 0xFF];
            temp ^= rcon[i/nk];
        } else if (nk > 6 && i % nk == 4) {
            // SubWord
            temp = (sbox[(temp >> 24) & 0xFF] << 24) | (sbox[(temp >> 16) & 0xFF] << 16) | (sbox[(temp >> 8) & 0xFF] << 8) | sbox[temp & 0xFF];
        }
        w[i] = w[i-nk] ^ temp;
    }
    // store
    for (i = 0; i < 4*(nr+1); i++) {
        roundkeys[4*i] = (w[i] >> 24) & 0xFF;
        roundkeys[4*i+1] = (w[i] >> 16) & 0xFF;
        roundkeys[4*i+2] = (w[i] >> 8) & 0xFF;
        roundkeys[4*i+3] = w[i] & 0xFF;
    }
}
```

