```c
static void key_expand(const uint8_t *key, int nk, int nr, uint8_t *rk) {
    uint32_t w[60]; // max 60 words for AES-256
    int i;
    for (i = 0; i < nk; i++)
        w[i] = ((uint32_t)key[4*i] << 24) | ((uint32_t)key[4*i+1] << 16) | ((uint32_t)key[4*i+2] << 8) | key[4*i+3];
    for (i = nk; i < 4*(nr+1); i++) {
        uint32_t t = w[i-1];
        if (i % nk == 0) {
            t = ((uint32_t)sbox[(t >> 16) & 0xff] << 24) | ((uint32_t)sbox[(t >> 8) & 0xff] << 16) | ((uint32_t)sbox[t & 0xff] << 8) | sbox[(t >> 24) & 0xff];
            t ^= rcon[i/nk - 1];
        } else if (nk > 6 && i % nk == 4) {
            t = ((uint32_t)sbox[(t >> 24) & 0xff] << 24) | ((uint32_t)sbox[(t >> 16) & 0xff] << 16) | ((uint32_t)sbox[(t >> 8) & 0xff] << 8) | sbox[t & 0xff];
        }
        w[i] = w[i-nk] ^ t;
    }
    for (i = 0; i < 4*(nr+1); i++) {
        rk[4*i] = (w[i] >> 24) & 0xff;
        rk[4*i+1] = (w[i] >> 16) & 0xff;
        rk[4*i+2] = (w[i] >> 8) & 0xff;
        rk[4*i+3] = w[i] & 0xff;
    }
}
```

