// Multiply two 128-bit values (in GF(2)) producing 256-bit result in (lo, hi)
static inline void clmul128(__m128i a, __m128i b, __m128i *lo, __m128i *hi) {
    __m128i t0 = _mm_clmulepi64_si128(a, b, 0x00); // a0*b0
    __m128i t1 = _mm_clmulepi64_si128(a, b, 0x01); // a0*b1
    __m128i t2 = _mm_clmulepi64_si128(a, b, 0x10); // a1*b0
    __m128i t3 = _mm_clmulepi64_si128(a, b, 0x11); // a1*b1
    // combine
    // lo = t0 ^ (t1 << 64) ^ (t2 << 64)
    // hi = t3 ^ (t1 >> 64) ^ (t2 >> 64)
    __m128i t1l = _mm_slli_si128(t1, 8); // t1 << 64
    __m128i t2l = _mm_slli_si128(t2, 8);
    __m128i t1h = _mm_srli_si128(t1, 8); // t1 >> 64
    __m128i t2h = _mm_srli_si128(t2, 8);
    *lo = _mm_xor_si128(t0, _mm_xor_si128(t1l, t2l));
    *hi = _mm_xor_si128(t3, _mm_xor_si128(t1h, t2h));
}
```

