// Reduce 256-bit (lo, hi) mod x^128 + x^7 + x^2 + x + 1
static inline __m128i gcm_reduce(__m128i lo, __m128i hi) {
    // R = x^7 + x^2 + x + 1 = 0x87
    const __m128i R = _mm_set_epi64x(0, 0x87);
    // hi * R
    __m128i t0 = _mm_clmulepi64_si128(hi, R, 0x00); // hi0 * R (low 64 * low 64)
    __m128i t1 = _mm_clmulepi64_si128(hi, R, 0x10); // hi1 * R (high 64 * low 64)
    __m128i t1_shifted = _mm_slli_si128(t1, 8); // t1 << 64
    __m128i t1_high = _mm_srli_si128(t1, 8); // t1 >> 64 (top bits of hi1*R)
    __m128i t2 = _mm_clmulepi64_si128(t1_high, R, 0x00); // (top bits) * R
    return _mm_xor_si128(lo, _mm_xor_si128(t0, _mm_xor_si128(t1_shifted, t2)));
}
