// Process 4 blocks: Y = ((((Y^B0)*H ^ B1)*H ^ B2)*H ^ B3)*H
// = (Y^B0)*H4 ^ B1*H3 ^ B2*H2 ^ B3*H
static inline __m128i ghash_4(__m128i Y, const __m128i *blocks, __m128i H, __m128i H2, __m128i H3, __m128i H4) {
    __m128i lo, hi, acc_lo, acc_hi;
    // term0 = (Y ^ B0) * H4
    clmul128(_mm_xor_si128(Y, blocks[0]), H4, &lo, &hi);
    acc_lo = lo; acc_hi = hi;
    // term1 = B1 * H3
    clmul128(blocks[1], H3, &lo, &hi);
